export const ROBOT_REACTIONS = Object.freeze(rows.map(([id,label,eyes,mouth,effect,motion,holdMs,energy,emotions,contexts,avoid,next],index)=>{
  if(!ROBOT_EYES.includes(eyes)||!ROBOT_MOUTHS.includes(mouth)||!ROBOT_EFFECTS.includes(effect)||!ROBOT_MOTIONS.includes(motion))throw Error(`Invalid robot reaction ${id}`);
  return Object.freeze({id,index,label,eyes,mouth,effect,motion,holdMs,energy,emotions,contexts,avoid,next:Object.freeze([...next])});
}));
const byId=new Map(ROBOT_REACTIONS.map(r=>[r.id,r]));
for(const r of ROBOT_REACTIONS)for(const id of r.next)if(!byId.has(id))throw Error(`Unknown continuation ${id} in ${r.id}`);
export const robotReaction=id=>byId.get(id)??null;

// Shown to the classifier. The device-only render fields are omitted.
export const ROBOT_REACTION_CHOICES=Object.freeze(Object.fromEntries(ROBOT_REACTIONS.filter(r=>r.id!=='hello').map(r=>[r.id,
  `${r.label}：情绪${r.emotions}；强度0平静至3强烈：${r.energy}；适合：${r.contexts}；避免：${r.avoid}。`])));
